prelude:
template <class A, class B> constexpr bool same = false;
template <class A> constexpr bool same<A, A> = true;
struct Box { int v = 0; };
template <class T> struct Trip { static_assert(!same<T, Box>, "the constraint is checked for Box"); static constexpr bool value = true; };

cols.f(Box&) + template f(const T&):
void f(Box&) {}
void f(const Box&) {}
template <class T> requires Trip<T>::value void f(const T&) {}

cols.f(Box&&) + f(const Box&) + template f(T&:
void f(Box&&) {}
void f(const Box&) {}
template <class T> requires Trip<T>::value void f(T&&) {}
